import numpy as np

def can_reach(input_grid, i, j):
    rows, cols = len(input_grid), len(input_grid[0])
    # Check row - can we go left/right to find a 9?
    if any(input_grid[i][k] == 9 for k in range(cols) if k > j) or \
       any(input_grid[i][k] == 9 for k in range(cols) if k < j):
        return True
    # Check column - can we go up/down to find a 9?
    if any(input_grid[k][j] == 9 for k in range(rows) if k > i) or \
       any(input_grid[k][j] == 9 for k in range(rows) if k < i):
        return True
    return False

def transform_rule3(input_grid):
    rows, cols = len(input_grid), len(input_grid[0])
    output = [[4]*cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if input_grid[i][j] == 9:
                output[i][j] = 9
            elif input_grid[i][j] == 4:
                if can_reach(input_grid, i, j):
                    output[i][j] = 2
                else:
